import type { MultiSelectSearchProps } from "../multi-select.types";

import { forwardRef, useImperativeHandle, useRef, useEffect, useState } from "react";
import { clsx } from "clsx";
import { Input } from "@components/input";
import { Search } from "@exp-textura/icons";
import { useTheme } from "@theme";

import { useMultiSelect } from "../hooks/use-multi-select";
import { MultiSelectClasses } from "../multi-select.styles";

export const MultiSelectSearch = forwardRef<HTMLInputElement, MultiSelectSearchProps>(
  ({ className, ...props }, ref) => {
    const {
      searchRef,
      searchValue,
      setSearchValue,
      handleKeyDown,
      contentId,
      activeDescendant,
      open,
      setHasSearch,
      setIsFiltering,
    } = useMultiSelect();
    const theme = useTheme();
    const inputRef = useRef<HTMLInputElement>(null);
    const [isFocused, setIsFocused] = useState(false);

    useEffect(() => {
      setHasSearch(true);
      return () => {
        setHasSearch(false);
      };
    }, [setHasSearch]);

    useImperativeHandle(ref, () => inputRef.current as HTMLInputElement);
    useImperativeHandle(searchRef, () => inputRef.current as HTMLInputElement);

    useEffect(() => {
      if (open && !isFocused) {
        inputRef.current?.focus();
      }
    }, [open, isFocused]);

    return (
      <Input
        className={clsx(MultiSelectClasses.search, className)}
        styleSlots={{
          root: { width: "100%" },
          inputWrapper: {
            borderBottomLeftRadius: 0,
            borderBottomRightRadius: 0,
            borderTop: "none",
            borderLeft: "none",
            borderRight: "none",
            paddingInlineStart: theme.toRem(theme.spacing[16]),
          },
          inputWrapperFocus: {
            boxShadow: "none",
          },
        }}
        {...props}
        ref={inputRef}
        aria-activedescendant={activeDescendant}
        aria-autocomplete="list"
        aria-controls={contentId}
        aria-expanded={open}
        autoComplete="off"
        role="combobox"
        value={searchValue}
        onBlur={() => setIsFocused(false)}
        onChange={(e) => {
          e.stopPropagation();
          setIsFiltering(true);
          setSearchValue((e.target as HTMLInputElement).value);
        }}
        onFocus={() => setIsFocused(true)}
        onKeyDown={handleKeyDown}
      >
        <Input.Prefix aria-hidden>
          <Search />
        </Input.Prefix>
      </Input>
    );
  },
);
MultiSelectSearch.displayName = "MultiSelect.Search";
